-- Content from the Jopearl Homemakers International company profile.
-- Replaces the services and updates the website text. Logo, colours, sizes and photos are NOT changed.

-- Services
DELETE FROM services;
INSERT INTO services (slug, title, summary, description, image, sort_order, active) VALUES ('project-design-and-rendering', 'Project Design and Rendering', 'See your space in full detail before a single wall is touched.', 'Every great project starts with a clear design. We develop concepts, layouts, material and colour schemes, then produce realistic 3D renders, so you can see exactly how your home or commercial space will look and feel before work begins.

Our designs are created around your specifications and preferences, and refined with you until you''re completely happy.', 'https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1600&q=80', 0, 1);
INSERT INTO services (slug, title, summary, description, image, sort_order, active) VALUES ('space-planning', 'Space Planning', 'Layouts that make every square metre work beautifully.', 'Good design begins with how a space flows. We study how you live or work, then plan the layout of rooms, furniture, storage, lighting and circulation, so every area is comfortable, practical and beautiful.

Whether it''s a single room, a full apartment or a commercial floor, space planning ensures nothing is wasted and everything has its place.', 'https://images.unsplash.com/photo-1600210491892-03d54c0aaf87?auto=format&fit=crop&w=1600&q=80', 1, 1);
INSERT INTO services (slug, title, summary, description, image, sort_order, active) VALUES ('hardware-interior-exterior-finishing', 'Hardware Interior & Exterior Finishing', 'The fixed finishes that give a building its quality, from carcass to completion.', 'We take projects from carcass to completion, handling the permanent finishes that define a space inside and out. This includes ceilings, flooring, wall finishes and cladding, built-in joinery, kitchens and wardrobes, doors, and exterior and facade finishing.

We use only genuine materials and skilled workmanship, so the finish looks exceptional and stands the test of time.', 'https://images.unsplash.com/photo-1671197244266-73129c97c096?auto=format&fit=crop&w=1600&q=80', 2, 1);
INSERT INTO services (slug, title, summary, description, image, sort_order, active) VALUES ('software-interior-finishing-and-furnishing', 'Software Interior Finishing and Furnishing', 'Furniture, fabrics, lighting and décor that bring the space to life.', 'Once the structure is complete, we furnish and style it. We source and install furniture, curtains and blinds, rugs, decorative lighting, wall art, accessories and soft furnishings, all chosen to complete the design and reflect your taste.

The result is a finished, move-in-ready space that truly lets you experience the difference.', 'https://images.unsplash.com/photo-1616594039964-ae9021a400a0?auto=format&fit=crop&w=1600&q=80', 3, 1);
INSERT INTO services (slug, title, summary, description, image, sort_order, active) VALUES ('facility-management-services', 'Facility Management Services', 'Keeping your property in excellent condition long after handover.', 'A beautiful space deserves to stay beautiful. Our facility management services help residential and commercial property owners keep their buildings well maintained, functional and presentable, with planned upkeep and prompt attention when something needs fixing.

Talk to us about a maintenance arrangement that suits your property.', 'https://images.unsplash.com/photo-1604328698692-f76ea9498e76?auto=format&fit=crop&w=1600&q=80', 4, 1);

