UPDATE settings SET value = json_set(value, '$.eyebrow', 'Since 2006 · Luxury Designs', '$.title', 'Luxury designs, from carcass to finishing', '$.subtitle', 'Project design and execution for residential and commercial spaces. Over 3,000 projects delivered in 20 years, always with genuine materials and to your exact specification.', '$.primaryCta', json('{"label":"Our Services","to":"/services"}'), '$.secondaryCta', json('{"label":"Get a Quote","to":"/quote"}')), updated_at = datetime('now') WHERE key = 'hero';
UPDATE settings SET value = json_set(value, '$.introTitle', 'Extraordinary designs, delivered with genuine materials.', '$.introText', 'Jo-pearl Homemakers International was established on 10th July 2006. We design and execute residential and commercial projects from carcass to finishing and furnishing, always according to our clients'' specifications and preferences.

We create extraordinary designs for every project category, with high professionalism and, most importantly, genuine materials. We don''t compromise, and we always deliver the very best.', '$.stats', json('[{"value":"2006","label":"Established"},{"value":"3,000+","label":"Projects delivered"},{"value":"20 yrs","label":"Of excellence"}]'), '$.process', json('[{"title":"Brief & site visit","text":"We listen to your needs, visit the site and agree your specifications, style and budget."},{"title":"Design & rendering","text":"Space planning, drawings and 3D renders, so you see the finished space before work starts."},{"title":"Execution","text":"Hardware and software finishing, from carcass to furnishing, using genuine materials only."},{"title":"Handover & care","text":"A finished masterpiece, then facility management to keep it at its best."}]'), '$.ctaText', 'Tell us about your residential or commercial project and we''ll get back to you with ideas and a quotation.'), updated_at = datetime('now') WHERE key = 'home';
UPDATE settings SET value = json_set(value, '$.title', 'About Jo-pearl Homemakers International', '$.intro', 'Established on 10th July 2006. Over 3,000 projects delivered across 20 years.', '$.story', 'Jo-pearl Homemakers International was established on 10th July 2006. Over the past 20 years we have delivered more than 3,000 projects, always ensuring excellent service delivery according to our clients'' specifications and preferences.

We design and execute from carcass to finishing and furnishing, for both residential and commercial projects. Our projects are exceptional and always a masterpiece, hence our slogan: ...experience the difference.

For many years since 2006, we have created mind-blowing innovations and unique designs. We look forward to partnering with you on your project, and we''re committed to rendering exceptional service delivery.

Jo-pearl Homemakers is a member of Jopearl Int''l Ltd (RC 958458).', '$.values', json('[{"title":"Genuine materials","text":"We never cut corners on materials. Quality you can see and feel for years."},{"title":"Your specification","text":"Every project is delivered according to your specifications and preferences."},{"title":"Carcass to furnishing","text":"One team from the bare structure to the final finishing and furnishing."},{"title":"Only the very best","text":"We don''t compromise. Every project is designed and delivered as a masterpiece."}]')), updated_at = datetime('now') WHERE key = 'about';
UPDATE settings SET value = json_set(value, '$.portfolioIntro', 'A selection of the residential and commercial projects we''ve designed and delivered.', '$.servicesIntro', 'Design, planning, finishing, furnishing and facility management: one team for the whole life of your space.', '$.quoteIntro', 'Tell us about your project. The more detail you share, the more accurate our quotation will be.', '$.contactIntro', 'Call, WhatsApp, email or visit our office in Lekki. We look forward to partnering with you on your project.'), updated_at = datetime('now') WHERE key = 'pages';
