INSERT INTO faqs (question, answer, sort_order) VALUES ('How long have you been in business?', 'Jopearl Homemakers International was established on 10th July 2006. Over the past 20 years we have delivered more than 3,000 projects, always according to our clients'' specifications and preferences.', 6);
INSERT INTO faqs (question, answer, sort_order) VALUES ('Do you handle the whole project, or only the design?', 'Both. We design and execute from carcass to finishing and furnishing: design and rendering, space planning, hardware interior and exterior finishing, and software finishing and furnishing. After handover, we also offer facility management.', 7);
INSERT INTO faqs (question, answer, sort_order) VALUES ('What is facility management?', 'It''s how we help you keep your property in excellent condition after the project is finished, with planned maintenance and prompt attention when something needs fixing. Contact us to discuss what your property needs.', 8);
INSERT INTO faqs (question, answer, sort_order) VALUES ('Where is your office?', 'Our office is at Friends Colony Estate, Osapa London, Lekki, Lagos. Call or WhatsApp +234 703 130 6790 to arrange a visit.', 9);

